measurement.script:
param([string]$Original, [string]$Current, [string]$Root)
$ErrorActionPreference = 'Stop'
$records = [Collections.Generic.List[object]]::new()
$sampleRoot = Join-Path $Root 'workspace-measure-fixture'
[void][IO.Directory]::CreateDirectory($sampleRoot)
$candidates = @(0..9 | ForEach-Object { @{Name="entry-$_"; LastUsed=([datetime]'2020-01-01').AddDays($_); SizeBytes=1} })
foreach ($pair in -2..6) {
    $variants = @('original', 'typed')
    if ($pair % 2 -ne 0) { [array]::Reverse($variants) }
    foreach ($variant in $variants) {
        if ($variant -eq 'original') { . $Original } else { . $Current }
        foreach ($scenario in @('workspace', 'prune', 'retention-empty')) {
            $clock = [Diagnostics.Stopwatch]::StartNew()
            switch ($scenario) {
                workspace { $value = Resolve-UnityProjectWorkspace -RepoRoot $sampleRoot -Version '6000.6.0f1' -Mode playmode -ShareEditorProject -Scope ' single-threaded ' -GenerationFingerprint '0123456789abcdef' }
                prune { $value = @(Get-PersistentProjectPruneOrder -Candidates $candidates -FreeBytes 0 -MinimumFreeBytes 5) }
                retention-empty { $value = Move-UnityProjectWithMigrationResidue -Project $sampleRoot }
            }
            $clock.Stop()
            if ($scenario -eq 'workspace' -and $value.LeafName -ne 'f-09d2bebc44c97016') { throw 'Workspace result mismatch.' }
            if ($scenario -eq 'prune' -and ($value -join ',') -ne 'entry-0,entry-1,entry-2,entry-3,entry-4') { throw 'Prune result mismatch.' }
            if ($scenario -eq 'retention-empty' -and $null -ne $value) { throw 'Unexpected retention mutation.' }
            $records.Add(@{pair=$pair; variant=$variant; scenario=$scenario; milliseconds=$clock.Elapsed.TotalMilliseconds})
        }
    }
}
ConvertTo-Json -InputObject $records.ToArray() -Depth 10 -Compress
